ALTER TABLE `reclamo`
  ADD COLUMN `motivo` enum('NO_RECIBI_PEDIDO','FALTAN_PRODUCTOS','PRODUCTOS_EQUIVOCADOS','PRODUCTO_EN_MAL_ESTADO','COBRO_INCORRECTO','OTRO') NULL AFTER `pedido_id`,
  ADD COLUMN `tipo_resolucion` enum('REEMBOLSO_TOTAL','REEMBOLSO_PARCIAL','RECHAZO') NULL AFTER `estado`,
  ADD COLUMN `monto_aprobado` decimal(10,2) NULL AFTER `tipo_resolucion`,
  ADD KEY `idx_reclamo_estado_fecha` (`estado`,`fecha_creacion`),
  ADD CONSTRAINT `ck_reclamo_resolucion` CHECK (
    (`estado` = 'PENDIENTE' AND `tipo_resolucion` IS NULL AND `monto_aprobado` IS NULL AND `administrador_id` IS NULL AND `fecha_resolucion` IS NULL)
    OR (`estado` = 'APROBADO' AND `tipo_resolucion` IN ('REEMBOLSO_TOTAL','REEMBOLSO_PARCIAL') AND `monto_aprobado` > 0 AND `administrador_id` IS NOT NULL AND `fecha_resolucion` IS NOT NULL)
    OR (`estado` = 'RECHAZADO' AND `tipo_resolucion` = 'RECHAZO' AND `monto_aprobado` IS NULL AND `nota_resolucion` IS NOT NULL AND `administrador_id` IS NOT NULL AND `fecha_resolucion` IS NOT NULL)
  );

ALTER TABLE `nota_credito`
  ADD COLUMN `reclamo_id` int(11) NULL AFTER `pago_id`,
  ADD UNIQUE KEY `uq_nota_credito_reclamo` (`reclamo_id`),
  ADD CONSTRAINT `fk_nota_credito_reclamo` FOREIGN KEY (`reclamo_id`) REFERENCES `reclamo` (`id`);

ALTER TABLE `notificacion`
  MODIFY COLUMN `tipo` enum('NUEVO_PEDIDO','PEDIDO_ACEPTADO','PEDIDO_RECHAZADO','PEDIDO_EN_CAMINO','PEDIDO_LISTO_RETIRO','AVISO_75MIN_SIN_CONFIRMACION','PEDIDO_AUTOCONFIRMADO','PEDIDO_CANCELADO_CLIENTE','PEDIDO_ANULADO_COMERCIO','PEDIDO_CANCELADO_SISTEMA','PEDIDO_EXPIRADO_CLIENTE','PEDIDO_EXPIRADO_COMERCIO','COMERCIO_APROBADO','COMERCIO_RECHAZADO','COMERCIO_SUSPENDIDO','NUEVO_COMERCIO_PENDIENTE','NUEVA_RESOLICITUD_COMERCIO','NUEVO_RECLAMO','RECLAMO_APROBADO','RECLAMO_RECHAZADO','NUEVO_MENSAJE_SOPORTE','PRODUCTO_REMOVIDO_CARRITO','CUENTA_INACTIVADA','COMERCIO_INACTIVADO','PEDIDO_CERRADO_TIMER_SUSPENSION','REEMBOLSO_FALLIDO_DEFINITIVO','CLIENTE_SUSPENDIDO','SUSPENSION_LEVANTADA','PEDIDO_AUTOCONFIRMADO_COMERCIO','INVITACION_EMPLEADO','EMPLEADO_DESACTIVADO','PEDIDO_NO_RETIRADO','EMPLEADO_REACTIVADO','DOCUMENTO_APROBADO','DOCUMENTO_RECHAZADO','COMERCIO_APTO_VENTA','COMERCIO_SIN_APTITUD','COMERCIO_SUSPENDIDO_EQUIPO','COMERCIO_SUSPENSION_LEVANTADA_EQUIPO','DUENO_SUSPENDIDO','DUENO_SUSPENSION_LEVANTADA','RECLAMO_REEMBOLSO_DUENO') NOT NULL;
